219	/* Return NULL if failed */
220	static Primitive *get_primitive(Cell const *cell, double const symprec,
221	                                double const angle_tolerance) {
222	    int attempt;
223	    double tolerance;
224	    Primitive *primitive;
225	    VecDBL *pure_trans;
226	
227	    debug_print("get_primitive (tolerance = %f):\n", symprec);
228	
229	    primitive = NULL;
230	    pure_trans = NULL;
231	
232	    if ((primitive = prm_alloc_primitive(cell->size)) == NULL) {
233	        goto notfound;
234	    }
235	
236	    tolerance = symprec;
237	    for (attempt = 0; attempt < NUM_ATTEMPT; attempt++) {
238	        debug_print("get_primitive (attempt = %d):\n", attempt);
239	        if ((pure_trans = sym_get_pure_translation(cell, tolerance)) != NULL) {
240	            if (prm_get_primitive_with_pure_trans(primitive, cell, pure_trans,
241	                                                  tolerance, angle_tolerance)) {
242	                goto found;
243	            }
244	        }
245	
246	        mat_free_VecDBL(pure_trans);
247	        pure_trans = NULL;
248	
249	        tolerance *= REDUCE_RATE;
250	        debug_print("spglib: Reduce tolerance to %f ", tolerance);
251	    }
252	
253	    prm_free_primitive(primitive);
254	    primitive = NULL;
255	
256	notfound:
257	    return NULL;
258	
259	found:
260	    mat_free_VecDBL(pure_trans);
261	    pure_trans = NULL;
262	    return primitive;
263	}
