443	/* Return 0 if failed */
444	static int find_primitive_lattice_vectors(double prim_lattice[3][3],
445	                                          VecDBL const *vectors,
446	                                          Cell const *cell,
447	                                          double const symprec) {
448	    int i, j, k, size, aperiodic_axis;
449	    double initial_volume, volume;
450	    double relative_lattice[3][3], min_vectors[3][3], tmp_lattice[3][3];
451	    double inv_mat_dbl[3][3];
452	    int inv_mat_int[3][3];
453	
454	    debug_print("find_primitive_lattice_vectors:\n");
455	
456	    size = vectors->size;
457	    initial_volume = mat_Dabs(mat_get_determinant_d3(cell->lattice));
458	    aperiodic_axis = cell->aperiodic_axis;
459	
460	    /* check volumes of all possible lattices, find smallest volume */
461	    if (aperiodic_axis == -1) {
462	        for (i = 0; i < size; i++) {
463	            for (j = i + 1; j < size; j++) {
464	                for (k = j + 1; k < size; k++) {
465	                    mat_multiply_matrix_vector_d3(tmp_lattice[0], cell->lattice,
466	                                                  vectors->vec[i]);
467	                    mat_multiply_matrix_vector_d3(tmp_lattice[1], cell->lattice,
468	                                                  vectors->vec[j]);
469	                    mat_multiply_matrix_vector_d3(tmp_lattice[2], cell->lattice,
470	                                                  vectors->vec[k]);
471	                    volume = mat_Dabs(mat_get_determinant_d3(tmp_lattice));
472	                    if (volume > symprec) {
473	                        if (mat_Nint(initial_volume / volume) == size - 2) {
474	                            mat_copy_vector_d3(min_vectors[0], vectors->vec[i]);
475	                            mat_copy_vector_d3(min_vectors[1], vectors->vec[j]);
476	                            mat_copy_vector_d3(min_vectors[2], vectors->vec[k]);
477	                            goto ret;
478	                        }
479	                    }
480	                }
481	            }
482	        }
483	    } else {
484	        /* for layer, first move aperiodic axis to c */
485	        k = size + aperiodic_axis - 3;
486	
487	        for (i = 0; i < size; i++) {
488	            for (j = i + 1; j < size; j++) {
489	                if (i != k && j != k) {
490	                    mat_multiply_matrix_vector_d3(tmp_lattice[0], cell->lattice,
491	                                                  vectors->vec[i]);
492	                    mat_multiply_matrix_vector_d3(tmp_lattice[1], cell->lattice,
493	                                                  vectors->vec[j]);
494	                    mat_multiply_matrix_vector_d3(tmp_lattice[2], cell->lattice,
495	                                                  vectors->vec[k]);
496	                    volume = mat_Dabs(mat_get_determinant_d3(tmp_lattice));
497	                    if (volume > symprec) {
498	                        if (mat_Nint(initial_volume / volume) == size - 2) {
499	                            mat_copy_vector_d3(min_vectors[0], vectors->vec[i]);
500	                            mat_copy_vector_d3(min_vectors[1], vectors->vec[j]);
501	                            /* move aperiodic axis back */
502	                            if (aperiodic_axis == 2) {
503	                                mat_copy_vector_d3(min_vectors[2],
504	                                                   vectors->vec[k]);
505	                            } else {
506	                                mat_copy_vector_d3(min_vectors[2],
507	                                                   min_vectors[aperiodic_axis]);
508	                                mat_copy_vector_d3(min_vectors[aperiodic_axis],
509	                                                   vectors->vec[k]);
510	                            }
511	                            goto ret;
512	                        }
513	                    }
514	                }
515	            }
516	        }
517	    }
518	
519	    /* Not found */
520	    debug_print("spglib: Primitive lattice vectors could not be found\n");
521	    return 0;
522	
523	    /* Found */
524	ret:
525	    for (i = 0; i < 3; i++) {
526	        for (j = 0; j < 3; j++) {
527	            relative_lattice[j][i] = min_vectors[i][j];
528	        }
529	    }
530	
531	    mat_inverse_matrix_d3(inv_mat_dbl, relative_lattice, 0);
532	    mat_cast_matrix_3d_to_3i(inv_mat_int, inv_mat_dbl);
533	    if (abs(mat_get_determinant_i3(inv_mat_int)) == size - 2) {
534	        mat_cast_matrix_3i_to_3d(inv_mat_dbl, inv_mat_int);
535	        mat_inverse_matrix_d3(relative_lattice, inv_mat_dbl, 0);
536	    } else {
537	        warning_print("spglib: Primitive lattice cleaning is incomplete\n");
538	    }
539	    mat_multiply_matrix_d3(prim_lattice, cell->lattice, relative_lattice);
540	
541	    return 1;
542	}
