576	static VecDBL *collect_pure_translations(Symmetry const *symmetry) {
577	    int i, num_pure_trans;
578	    VecDBL *pure_trans;
579	    VecDBL *ret_pure_trans;
580	    static int identity[3][3] = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
581	    num_pure_trans = 0;
582	    pure_trans = NULL;
583	    ret_pure_trans = NULL;
584	
585	    if ((pure_trans = mat_alloc_VecDBL(symmetry->size)) == NULL) {
586	        return NULL;
587	    }
588	
589	    for (i = 0; i < symmetry->size; i++) {
590	        if (mat_check_identity_matrix_i3(symmetry->rot[i], identity)) {
591	            mat_copy_vector_d3(pure_trans->vec[num_pure_trans],
592	                               symmetry->trans[i]);
593	            num_pure_trans++;
594	        }
595	    }
596	
597	    if ((ret_pure_trans = mat_alloc_VecDBL(num_pure_trans)) == NULL) {
598	        mat_free_VecDBL(pure_trans);
599	        pure_trans = NULL;
600	        return NULL;
601	    }
602	
603	    for (i = 0; i < num_pure_trans; i++) {
604	        mat_copy_vector_d3(ret_pure_trans->vec[i], pure_trans->vec[i]);
605	    }
606	
607	    mat_free_VecDBL(pure_trans);
608	    pure_trans = NULL;
609	
610	    return ret_pure_trans;
611	}
