613	static int get_primitive_in_translation_space(double t_mat_inv[3][3],
614	                                              VecDBL const *pure_trans,
615	                                              int const symmetry_size,
616	                                              double const symprec) {
617	    int i, j, primsym_size;
618	    Primitive *primitive;
619	    Cell *cell;
620	
621	    cell = NULL;
622	    primitive = NULL;
623	
624	    if ((cell = cel_alloc_cell(pure_trans->size, NOSPIN)) == NULL) {
625	        return 0;
626	    }
627	
628	    primsym_size = symmetry_size / pure_trans->size;
629	    if (symmetry_size != primsym_size * pure_trans->size) {
630	        cel_free_cell(cell);
631	        cell = NULL;
632	        return 0;
633	    }
634	
635	    for (i = 0; i < pure_trans->size; i++) {
636	        cell->types[i] = 1;
637	        for (j = 0; j < 3; j++) {
638	            cell->position[i][j] = pure_trans->vec[i][j];
639	        }
640	    }
641	
642	    for (i = 0; i < 3; i++) {
643	        for (j = 0; j < 3; j++) {
644	            if (i == j) {
645	                cell->lattice[i][j] = 1;
646	            } else {
647	                cell->lattice[i][j] = 0;
648	            }
649	        }
650	    }
651	
652	    primitive = get_primitive(cell, symprec, -1.0);
653	    cel_free_cell(cell);
654	    cell = NULL;
655	
656	    if (primitive == NULL) {
657	        return 0;
658	    }
659	
660	    if (primitive->cell->size != 1) {
661	        prm_free_primitive(primitive);
662	        primitive = NULL;
663	        return 0;
664	    }
665	
666	    mat_copy_matrix_d3(t_mat_inv, primitive->cell->lattice);
667	    prm_free_primitive(primitive);
668	    primitive = NULL;
669	
670	    return 1;
671	}
