def trans(A): return [[A[j][i] for j in range(3)] for i in range(3)]
def det3(A):
    return A[0][0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1])-A[0][1]*(A[1][0]*A[2][2]-A[1][2]*A[2][0])+A[0][2]*(A[1][0]*A[2][1]-A[1][1]*A[2][0])
INV=[[-1,0,0],[0,-1,0],[0,0,-1]]
def get_rotation_type(A):
    d=det3(A); t=sum(A[i][i] for i in range(3))
    return d,t
def proper(A):
    return matmul(INV,A) if det3(A)==-1 else A
def axis_of(A):
    # solve (A-I)v=0 via cross product of two rows
    M=[[A[i][j]-(1 if i==j else 0) for j in range(3)] for i in range(3)]
    # try each pair of rows cross
    import itertools
    for i,j in itertools.permutations(range(3),2):
        r1,r2=M[i],M[j]
        c=[r1[1]*r2[2]-r1[2]*r2[1], r1[2]*r2[0]-r1[0]*r2[2], r1[0]*r2[1]-r1[1]*r2[0]]
        if any(abs(x)>1e-9 for x in c):
            return c
    return [1,0,0]
