#include <stdio.h>
#include <string.h>
#include <math.h>
#include "spglib.h"
#include "mathfunc.h"

static void m3(const char*n,int m[3][3]){printf("%s:\n",n);for(int i=0;i<3;i++){for(int j=0;j<3;j++)printf("%4d ",m[i][j]);printf("\n");}}
static void d3(const char*n,double m[3][3]){printf("%s:\n",n);for(int i=0;i<3;i++){for(int j=0;j<3;j++)printf("%9.5f ",m[i][j]);printf("\n");}}
static void printvec(const char*n,double v[3]){printf("%s=(%f %f %f)\n",n,v[0],v[1],v[2]);}

int main(void){
  double orig[3][3] = {
    {6.690190420309425, -6.188581736674, -1.00321736727},
    {0.0, 5.533016477339, -1.122081002728},
    {0.0, 0.0, 3.340347224066}
  };
  int rot[4][3][3] = {
    {{1,0,0},{0,1,0},{0,0,1}},
    {{-1,0,0},{0,-1,0},{-1,0,1}},
    {{1,-2,0},{0,-1,0},{0,-1,1}},
    {{-1,2,0},{0,1,0},{-1,1,1}},
  };
  double trans[4][3] = {{0,0,0},{0,0,0},{0,0.5,0.25},{0,0.5,0.25}};

  // copy to reduce
  double red[3][3];
  mat_copy_matrix_d3(red, orig);
  int ok = spg_delaunay_reduce(red, 0.01);
  printf("delaunay ok=%d err=%d\n", ok, spg_get_error_code());
  d3("reduced", red);

  // P = red * inv(orig) : fractional coords transform p_red = P p_orig
  double inv_orig[3][3], P[3][3];
  mat_inverse_matrix_d3(inv_orig, orig, 0);
  mat_multiply_matrix_d3(P, red, inv_orig);
  d3("P (frac red = P frac orig)", P);
  // cast to int (should be unimodular)
  int Pi[3][3];
  mat_cast_matrix_3d_to_3i(Pi, P);
  m3("P int", Pi);

  // transform ops: (R,t) in orig basis -> R' = P R P^-1, t' = P t
  double Pinv[3][3], Rtd[3][3], tmp[3][3];
  mat_inverse_matrix_d3(Pinv, P, 0);
  int rot2[4][3][3]; double trans2[4][3];
  for(int i=0;i<4;i++){
    mat_cast_matrix_3i_to_3d(tmp, rot[i]);
    mat_multiply_matrix_d3(Rtd, P, tmp);
    mat_multiply_matrix_d3(Rtd, Rtd, Pinv);
    mat_cast_matrix_3d_to_3i(rot2[i], Rtd);
    mat_multiply_matrix_vector_d3(trans2[i], P, trans[i]);
  }
  // also transform lattice: L_red = L_orig P^T? Actually lattice rows: L_red = P^T? 
  // We reduced via spg_delaunay_reduce which gives red directly. Use red as lattice.
  d3("using red lattice for call", red);
  for(int i=0;i<4;i++){m3("rot2", rot2[i]); printvec("t2", trans2[i]);}

  SpglibSpacegroupType t = spg_get_spacegroup_type_from_symmetry(rot2, trans2, 4, red, 0.01);
  printf("RESULT reduced+transformed: n=%d hall=%d err=%d\n", t.number, t.hall_number, spg_get_error_code());
  return 0;
}
