        goto err;
    }
    mat_multiply_matrix_d3(prim_lat, lattice, t_mat_inv);
} else {
    mat_copy_matrix_d3(prim_lat, lattice);
}

/* Reduce the primitive lattice to a Delaunay cell and express the
 * symmetry operations in that (shortest) basis before the space group
 * search. The point-group axis lookup relies on integer axis vectors
 * that fit in the reduced basis; a skewed input basis can make the
 * same physical axes have components outside the lookup table, which
 * would otherwise mis-identify the space group. This mirrors the
 * lattice preparation performed for structure-based identification. */
mat_copy_matrix_d3(red_lat, prim_lat);
reduce_status = del_delaunay_reduce(red_lat, prim_lat, symprec);
if (reduce_status &&
    (mat_get_determinant_d3(prim_lat) > symprec) &&
    (mat_get_determinant_d3(red_lat) > symprec)) {
    if (mat_inverse_matrix_d3(inv_prim_lat, prim_lat, symprec) &&
        mat_inverse_matrix_d3(change_inv, red_lat, symprec)) {
        /* change: fractional coordinates in prim_lat basis to those in
         * the reduced (Delaunay) basis. */
        mat_multiply_matrix_d3(change, inv_prim_lat, red_lat);
        mat_cast_matrix_3d_to_3i(red_change, change);
        mat_cast_matrix_3i_to_3d(change, red_change);
        if (mat_inverse_matrix_d3(change_inv, change, symprec)) {
            for (i = 0; i < prim_symmetry->size; i++) {
                mat_cast_matrix_3i_to_3d(rot_d3, prim_symmetry->rot[i]);
                mat_multiply_matrix_d3(tmp_mat, change, rot_d3);
                mat_multiply_matrix_d3(tmp_mat, tmp_mat, change_inv);
                mat_cast_matrix_3d_to_3i(prim_symmetry->rot[i], tmp_mat);
                mat_copy_vector_d3(tmp_vec, prim_symmetry->trans[i]);
                mat_multiply_matrix_vector_d3(prim_symmetry->trans[i],
                                              change, tmp_vec);
            }
            mat_copy_matrix_d3(prim_lat, red_lat);
        }
    }
}

spacegroup =
    spa_search_spacegroup_with_symmetry(prim_symmetry, prim_lat, symprec);

