#include <stdlib.h>
#include "spglib.h"
#include "mathfunc.h"
static void cell(double lat[3][3], double a,double b,double c,double al,double be,double ga){
  al*=M_PI/180; be*=M_PI/180; ga*=M_PI/180; double sg=sin(ga);
  lat[0][0]=a; lat[0][1]=b*cos(ga); lat[0][2]=0.0; lat[1][0]=0.0; lat[1][1]=b*sg; lat[1][2]=0.0;
  double cx=c*cos(be); double cy=c*(cos(al)-cos(be)*cos(ga))/sg; double cz=sqrt(c*c-cx*cx-cy*cy);
  lat[1][2]=cy; lat[0][2]=cx; lat[2][2]=cz; lat[2][0]=0.0; lat[2][1]=0.0;
}
// returns sg via ops-based
static int opsg(double lattice[3][3], int nops, int rotn[][3][3], double transn[][3]){
  SpglibSpacegroupType t = spg_get_spacegroup_type_from_symmetry(rotn, transn, nops, lattice, 0.01);
  return t.number;
}
