    for(int cc=0;cc<3;cc++)transn[i][cc]=d->translations[i][cc];}
  int sg_orig=opsg(lat,nop,rotn,transn);
  // skew: U unimodular (symmetric). A'=U^T A = U A; M=U^-1; R'=M R M^-1; t'=M t
  double U[3][3]={{1,1,1},{1,1,0},{1,0,1}};
  double lat2[3][3]; mat_multiply_matrix_d3(lat2, U, lat);
