      mat_cast_matrix_3i_to_3d(tmp, rotn[i]);
      mat_multiply_matrix_d3(Rtd, Minv, tmp); mat_multiply_matrix_d3(Rtd, Rtd, U);
      mat_cast_matrix_3d_to_3i(r2[i], Rtd);
      mat_multiply_matrix_vector_d3(t2[i], Minv, transn[i]);
    }
    sg_skew=opsg(lat2,nop,r2,t2);
  }
  // Also: build full skewed structure and run dataset on it (ground truth for skew)
  // positions transform: f' = M f = Minv f  (fractional, using U^-1)
  double pos2[64][3]; int types2[64];
  for(int i=0;i<n;i++){ mat_multiply_matrix_vector_d3(pos2[i], Minv, pos[i]);
    for(int j=0;j<3;j++){pos2[i][j]-=floor(pos2[i][j]);} types2[i]=types[i];}
