static int get_hall_number_from_symmetry(int const rotation[][3][3],
                                         double const translation[][3],
                                         int const num_operations,
                                         double const lattice[3][3],
                                         int const transform_lattice_by_tmat,
                                         double const symprec) {
    int i, hall_number, reduce_status;
    int red_change[3][3];
    Symmetry *symmetry;
    Symmetry *prim_symmetry;
    Spacegroup *spacegroup;
    double t_mat[3][3], t_mat_inv[3][3], prim_lat[3][3], red_lat[3][3];
    double inv_red_lat[3][3], change[3][3], change_inv[3][3], rot_d3[3][3];
    double tmp_mat[3][3], tmp_vec[3];

    symmetry = NULL;
    prim_symmetry = NULL;
    spacegroup = NULL;

    if ((symmetry = sym_alloc_symmetry(num_operations)) == NULL) {
        goto err;
    }

    for (i = 0; i < num_operations; i++) {
        mat_copy_matrix_i3(symmetry->rot[i], rotation[i]);
        mat_copy_vector_d3(symmetry->trans[i], translation[i]);
    }

    prim_symmetry = prm_get_primitive_symmetry(t_mat, symmetry, symprec);
    sym_free_symmetry(symmetry);
    symmetry = NULL;

    if (prim_symmetry == NULL) {
        goto err;
    }

    if (transform_lattice_by_tmat) {
        if (!mat_inverse_matrix_d3(t_mat_inv, t_mat, symprec)) {
            goto err;
        }
        mat_multiply_matrix_d3(prim_lat, lattice, t_mat_inv);
    } else {
        mat_copy_matrix_d3(prim_lat, lattice);
    }

    /* Reduce the primitive lattice to a Delaunay cell and express the
     * symmetry operations in that (shortest) basis before the space group
     * search. The point-group axis lookup relies on integer axis vectors
     * that fit in the reduced basis; a skewed input basis can make the
     * same physical axes have components outside the lookup table, which
     * would otherwise mis-identify the space group. This mirrors the
     * lattice preparation performed for structure-based identification. */
    mat_copy_matrix_d3(red_lat, prim_lat);
    reduce_status = del_delaunay_reduce(red_lat, prim_lat, symprec);
    if (reduce_status && (mat_get_determinant_d3(prim_lat) > symprec) &&
        (mat_get_determinant_d3(red_lat) > symprec) &&
        mat_inverse_matrix_d3(inv_red_lat, red_lat, symprec)) {
        /* change: maps symmetry operations from the prim_lat basis to the
         * reduced (Delaunay) basis. It is unimodular because the reduced
         * lattice is an integer re-basis of the primitive lattice. */
        mat_multiply_matrix_d3(change, inv_red_lat, prim_lat);
        mat_cast_matrix_3d_to_3i(red_change, change);
        mat_cast_matrix_3i_to_3d(change, red_change);
