                mat_cast_matrix_3i_to_3d(rot_d3, prim_symmetry->rot[i]);
                mat_multiply_matrix_d3(tmp_mat, change, rot_d3);
                mat_multiply_matrix_d3(tmp_mat, tmp_mat, change_inv);
                mat_cast_matrix_3d_to_3i(prim_symmetry->rot[i], tmp_mat);
