                mat_multiply_matrix_vector_d3(prim_symmetry->trans[i], change,
                                              tmp_vec);
            }
            mat_copy_matrix_d3(prim_lat, red_lat);
        }
    }

    spacegroup =
        spa_search_spacegroup_with_symmetry(prim_symmetry, prim_lat, symprec);
    sym_free_symmetry(prim_symmetry);
    prim_symmetry = NULL;
    if (spacegroup) {
        hall_number = spacegroup->hall_number;
        free(spacegroup);
        spacegroup = NULL;
    } else {
        goto err;
